+    [Fact]
+    public async Task ClosedGenericStruct_FromMetadataReference()
+    {
+        string defineSource = """
+using MessagePack;
+
+namespace TempProject
+{
+    [MessagePackObject]
+    public struct MyGenericStruct<T>
+    {
+        [Key(0)]
+        public T Content { get; set; }
+    }
+}
